public class OwnedLegacyAsync59 {
 public static List<String> callbacks=new List<String>();
 public static List<Database.SaveResult> send(List<SObject> draft,AccessLevel mode) {
  return Database.insertAsync(draft,new OwnedLegacyCallback59(),mode);
 }
 public static Map<String,Object> snapshot(List<Database.SaveResult> results,List<SObject> draft,String label) {
  List<Object> rows=new List<Object>();
  for(Database.SaveResult saved:results){
   Map<String,Object> row=new Map<String,Object>();
   try{row.put('raw',JSON.serialize(saved));}catch(Exception e){row.put('rawException',e.getTypeName()+'|'+e.getMessage());}
   try{row.put('success',saved.isSuccess());row.put('id',saved.getId());}catch(Exception e){row.put('resultException',e.getTypeName()+'|'+e.getMessage());}
   try{List<Object> errors=new List<Object>();List<Database.Error> es=saved.getErrors();row.put('errorsNull',es==null);if(es!=null){for(Database.Error error:es){errors.add(new Map<String,Object>{'statusCode'=>String.valueOf(error.getStatusCode()),'message'=>error.getMessage(),'fields'=>error.getFields()});}}row.put('errors',errors);}catch(Exception e){row.put('errorsException',e.getTypeName()+'|'+e.getMessage());}
   try{row.put('asyncLocator',Database.getAsyncLocator(saved));}catch(Exception e){row.put('locatorException',e.getTypeName()+'|'+e.getMessage());}
   rows.add(row);
  }
  List<Object> inputIds=new List<Object>();for(SObject input:draft){inputIds.add(input.Id);}
  List<String> callbackCopy=new List<String>();callbackCopy.addAll(callbacks);
  return new Map<String,Object>{'resultCount'=>results.size(),'results'=>rows,'inputIds'=>inputIds,'callbackCount'=>callbackCopy.size(),'callbacks'=>callbackCopy,'ownedRows'=>[SELECT COUNT() FROM Account WHERE Name=:label],'dmlStatements'=>Limits.getDmlStatements(),'dmlRows'=>Limits.getDmlRows()};
 }

 public static Map<String,Object> observe(String kind) {
  String label='OwnedLegacyAsync';
  List<SObject> draft=new List<SObject>{new Account(Name=label)};
  if(kind=='PUBLISH59')draft=new List<SObject>{new BatchApexErrorEvent()};
  List<Database.SaveResult> results=new List<Database.SaveResult>();
  callbacks.clear();
  Map<String,Object> beforeCall=snapshot(results,draft,label);
  Test.startTest();
  String callException=null;
  try {
   if(kind=='PUBLISH59')results=EventBus.publish(draft);
   else results=send(draft,kind=='INSERT59_USER'?AccessLevel.USER_MODE:AccessLevel.SYSTEM_MODE);
  }catch(Exception e){callException=e.getTypeName()+'|'+e.getMessage();}
  Map<String,Object> immediate=snapshot(results,draft,label);immediate.put('callException',callException);
  String stopException=null;
  try{Test.stopTest();}catch(Exception e){stopException=e.getTypeName()+'|'+e.getMessage();}
  Map<String,Object> afterStop=snapshot(results,draft,label);afterStop.put('stopException',stopException);
  return new Map<String,Object>{'row'=>kind,'beforeCall'=>beforeCall,'immediate'=>immediate,'afterStop'=>afterStop};
 }
}

