}

public class OwnedLegacyCallback59 extends DataSource.AsyncSaveCallback {
 public override void processSave(Database.SaveResult saved) {
  String observation=JSON.serialize(saved);
  OwnedLegacyAsync59.callbacks.add(observation);
  System.debug(LoggingLevel.ERROR,'OWNED_ASYNC_CALLBACK64|'+observation);
 }
}

public class OwnedLegacyPublish59 {
 public static Map<String,Object> snapshot(List<Database.SaveResult> results) {
  List<Object> rows=new List<Object>();
  for(Database.SaveResult saved:results) {
   List<Object> errors=new List<Object>();List<Database.Error> es=saved.getErrors();
   if(es!=null)for(Database.Error e:es)errors.add(new Map<String,Object>{'statusCode'=>String.valueOf(e.getStatusCode()),'message'=>e.getMessage(),'fields'=>e.getFields()});
   rows.add(new Map<String,Object>{'success'=>saved.isSuccess(),'id'=>saved.getId(),'errorsNull'=>es==null,'errors'=>errors,'raw'=>JSON.serialize(saved)});
  }
  return new Map<String,Object>{'resultCount'=>results.size(),'results'=>rows,'dmlStatements'=>Limits.getDmlStatements(),'dmlRows'=>Limits.getDmlRows()};
 }
 public static Map<String,Object> observe() {
  List<SObject> events=new List<SObject>{new BatchApexErrorEvent()};
  List<Database.SaveResult> results=new List<Database.SaveResult>();
  Map<String,Object> beforeCall=snapshot(results);
  Test.startTest();String callException=null;
  try{results=EventBus.publish(events);}catch(Exception e){callException=e.getTypeName()+'|'+e.getMessage();}
  Map<String,Object> immediate=snapshot(results);immediate.put('callException',callException);
  String stopException=null;try{Test.stopTest();}catch(Exception e){stopException=e.getTypeName()+'|'+e.getMessage();}
  Map<String,Object> afterStop=snapshot(results);afterStop.put('stopException',stopException);
  return new Map<String,Object>{'row'=>'PUBLISH59','beforeCall'=>beforeCall,'immediate'=>immediate,'afterStop'=>afterStop};
 }
}

